  null, null,
  null, '{"currency":"GBP","unit":"per person","read_at":"2026-08-21","tiers":[{"tier":"outside the uk, up to 3 years","amount":819},{"tier":"outside the uk, more than 3 years","amount":1618},{"tier":"inside the uk (extend, switch or update), up to 3 years","amount":943},{"tier":"inside the uk (extend, switch or update), more than 3 years","amount":1865},{"tier":"job on the immigration salary list, up to 3 years","amount":628},{"tier":"job on the immigration salary list, more than 3 years","amount":1235}]}'::jsonb,
